{"report_id":"R0001","study_id":"S001","title":"Adaptive Partition and Resource Allocation for Collaborative Inference Services in UAV Swarm","authors":"Y. Dong; J. Shi; S. Li; Y. Gao; Y. Zhu; J. Zhang; J. Huang","year":2026,"venue":"2026 IEEE International Conference on Web Services (ICWS)","doi":"10.1109/ICWS72778.2026.00154","pdf_path":"restart_2026_11_26/fulltext_retrieval/pdf/R0001.pdf","fields":{"identity":[{"subtopic":"bibliographic","status":"OBSERVED","finding":"2026 IEEE ICWS conference paper, 3 pages, CAPRI framework.","page":1,"locator":"Header","excerpt":"2026 IEEE International Conference on Web Services (ICWS)"}],"uav_architecture_role_and_topology":[{"subtopic":"cloud_edge_uav_hierarchy","status":"OBSERVED","finding":"N UAVs (10 evaluated) collaborate with M edge servers (4 evaluated) and 1 cloud server; UAVs act as task sources and initial inference nodes.","page":3,"locator":"III.A Simulation Setup","excerpt":"This experiment considers 10 UAVs, 4 ESs and one cloud server."}],"inference_model_task_and_dataset":[{"subtopic":"dnn_model_and_dataset","status":"OBSERVED","finding":"Generic L-layer DNN (convolutional and FC layers); evaluated with public drone delivery dataset [3] and real base station location dataset [4]; specific DNN architecture name not stated.","page":3,"locator":"III.A Simulation Setup","excerpt":"This paper adopts the public drone delivery dataset [3]. The edge servers utilize a real dataset of base station locations [4]."}],"partition_and_assignment":[{"subtopic":"two_point_layer_partition","status":"OBSERVED","finding":"Two partition points pk and qk split L-layer DNN across UAV, selected edge server mk, and optional cloud server ck (5 execution modes).","page":2,"locator":"II.A Inference Partitioning","excerpt":"There are five situations: 1. The inference service only executes on UAV."}],"decision_variables_objectives_constraints_and_solver":[{"subtopic":"optimization_and_solver","status":"OBSERVED","finding":"Minimizes weighted sum of latency and energy (alphaTk + Ek) over partition points pk, qk, ES selection mk, cloud flag ck, computing allocation lambda, bandwidth eta, and UAV frequency fn via PPO + KKT/convex subproblems.","page":2,"locator":"II.D-E Problem Formulation & PPO","excerpt":"Using PPO and convex optimization methods for solving."}],"compute_and_radio":[{"subtopic":"compute_and_radio_model","status":"OBSERVED","finding":"UAV CPU frequency fn bounded in [f_min, f_max] with DVFS (Eq. 10), edge computing ratio lambda_k,m, wireless bandwidth ratio eta_k,m with Shannon capacity and path-loss exponent mu.","page":3,"locator":"II.F Analytical Resource Allocation","excerpt":"the optimal value of the computation frequency is obtained as"}],"mobility_channel_intermittency_failure_and_recovery":[{"subtopic":"mobility_and_channel","status":"OBSERVED","finding":"UAV mobility alters UAV-ES distances dn,m and wireless channel gains; failure and recovery mechanisms are not modeled.","page":1,"locator":"I. INTRODUCTION","excerpt":"due to the mobility of UAVs, the relative distances between UAVs and servers change dynamically"}],"evaluation_platform_simulator_hardware_and_traces":[{"subtopic":"simulation_and_traces","status":"OBSERVED","finding":"Simulation using drone delivery dataset [3] and Australian base station locations [4]; simulator software and host hardware not reported.","page":3,"locator":"III.A Simulation Setup","excerpt":"This paper adopts the public drone delivery dataset [3]."}],"baselines_and_workloads":[{"subtopic":"baselines","status":"OBSERVED","finding":"7 baselines: local, DQN, cloud_only, no_local, edge_only, end_edge, no_energy.","page":3,"locator":"III.A Simulation Setup","excerpt":"We compare the proposed algorithm with the following baseline algorithm. 1.local"}],"outcomes_latency_energy_communication_accuracy_reliability_and_scalability":[{"subtopic":"reward_and_tradeoff","status":"OBSERVED","finding":"CAPRI achieves higher reward than all 7 baselines across convergence (Fig. 2) and varying alpha (Fig. 3); no exact numeric outcomes printed in text/tables.","page":3,"locator":"III.A Simulation Setup","excerpt":"where CAPRIC outperforms all other baseline methods."}],"sensitivity_and_variability":[{"subtopic":"alpha_sensitivity","status":"OBSERVED","finding":"Sensitivity to latency weight alpha plotted in Fig. 3; rewards decrease as alpha increases; no multi-seed variance reported.","page":3,"locator":"III.A Simulation Setup","excerpt":"Fig. 3 demonstrates the rewards on a, as a increases, the rewards of all methods exhibit a decreasing trend."}],"code_and_data":[{"subtopic":"code_availability","status":"NOT_REPORTED","finding":"","page":3,"locator":"III.A-IV","excerpt":"REFERENCES","reason":"No code repository URL or code availability statement found in paper."}],"funding_and_conflicts":[{"subtopic":"funding","status":"OBSERVED","finding":"Supported by National Science and Technology Major Project (2025ZD1401501), NSFC (62572484), and CUP Beijing (2462024XKQY003).","page":3,"locator":"IV. ACKNOWLEDGEMENTS","excerpt":"National Natural Science Foundation of China (No. 62572484)"},{"subtopic":"conflicts","status":"NOT_REPORTED","finding":"","page":3,"locator":"IV. ACKNOWLEDGEMENTS","excerpt":"IV. ACKNOWLEDGEMENTS","reason":"No conflict of interest statement present."}],"reported_limitations":[{"subtopic":"limitations","status":"NOT_REPORTED","finding":"","page":3,"locator":"III-IV","excerpt":"IV. ACKNOWLEDGEMENTS","reason":"No limitations section or explicit limitations statement in the 3-page paper."}]},"quantitative_claims":[],"unresolved":[{"field_or_metric":"outcomes_quantitative_values","reason":"Fig. 2 and Fig. 3 present reward values only as plots without exact numeric values in text or tables.","source_checked":"R0001.pdf p.3 Section III.A Fig. 2-3"},{"field_or_metric":"inference_model_name","reason":"Specific DNN architecture (e.g., ResNet/VGG) and parameter counts used in simulation are not named in III.A.","source_checked":"R0001.pdf p.3 Section III.A"}]}
{"report_id":"R0002","study_id":"S002","title":"Promise: Predictive and Cost-Optimal Migrations for Service-Continuous Edge Intelligence in Multi-UAV Networks","authors":"J. Zhang; M. Tao; R. Xie; Y. Zhang","year":2026,"venue":"2026 IEEE International Conference on Web Services (ICWS)","doi":"10.1109/ICWS72778.2026.00067","pdf_path":"restart_2026_11_26/fulltext_retrieval/pdf/R0002.pdf","fields":{"identity":[{"subtopic":"bibliographic","status":"OBSERVED","finding":"2026 IEEE ICWS conference paper, 9 pages, Promise scheme.","page":1,"locator":"Header","excerpt":"2026 IEEE International Conference on Web Services (ICWS)"}],"uav_architecture_role_and_topology":[{"subtopic":"multi_swarm_gcs","status":"OBSERVED","finding":"1 GCS at origin and 3 UAV swarms (5, 10, 15 UAVs = 30 UAVs total) in equilateral triangle (side 100 m); UAVs execute partitioned task modules and migrate across/within swarms.","page":7,"locator":"VII.A Experimental Settings","excerpt":"the numbers of UAVs in the three swarms are set to 5, 10, and 15, respectively."}],"inference_model_task_and_dataset":[{"subtopic":"resnet18_cifar10","status":"OBSERVED","finding":"ResNet-18 trained on CIFAR-10 for urban monitoring image classification.","page":7,"locator":"VII.A Experimental Settings","excerpt":"a ResNet-18 model trained on the CIFAR-10 dataset is adopted for image classification."}],"partition_and_assignment":[{"subtopic":"equal_two_module_split","status":"OBSERVED","finding":"Each task partitioned equally into 2 sequentially dependent modules assigned to UAVs within a swarm via Greedy allocation, then migrated via PDBH.","page":7,"locator":"VII.A Experimental Settings","excerpt":"Each generated task is equally partition into two task modules, which are distributed to different UAVs within the same swarm"}],"decision_variables_objectives_constraints_and_solver":[{"subtopic":"minlp_pdbh","status":"OBSERVED","finding":"MINLP minimizing weighted migration delay and energy (C_uav-mig + C_ser-mig) over cross-swarm UAV migration y and intra-swarm service migration x, decoupled into P1 and P2 (NP-hard) and solved via LST-GNN prediction + Prediction-Driven Blocked Hungarian (PDBH).","page":5,"locator":"V.A Problem Formulation","excerpt":"the migration problem is formulated as a MINLP to obtain the efficient migration strategy"}],"compute_and_radio":[{"subtopic":"heterogeneous_uav_specs","status":"OBSERVED","finding":"Bandwidth [16, 32] Mbps, compute [12, 36] TOPS; P_tx=2 W, P_rx=2 W, P_fly=1600 W, speed 5 m/s; hardware config S500, Pixhawk6C, Orin Nano 4GB/8GB.","page":7,"locator":"VII.A & Fig. 2(b)","excerpt":"Each UAV is configured with a communication bandwidth of [16, 32] Mbps and a computing power of [12, 36] TOPS"}],"mobility_channel_intermittency_failure_and_recovery":[{"subtopic":"failure_and_recovery_migration","status":"OBSERVED","finding":"Models cross-swarm flight, battery replacement return to GCS when B <= B_min, predictive pre-migration, and recovery migration under random UAV failure probability 0.0001 per time-slot.","page":7,"locator":"VII.A Experimental Settings","excerpt":"random UAV failures are introduced in each time-slot with a probability of 0.0001."}],"evaluation_platform_simulator_hardware_and_traces":[{"subtopic":"simulation_server","status":"OBSERVED","finding":"Simulation on Intel Core i5-12600KF 3.70 GHz CPU, 32 GB RAM; parameters grounded in S500/Orin Nano UAV platform.","page":7,"locator":"VII.A Experimental Settings","excerpt":"The experiments are conducted on a server equipped with an Intel(R) Core(TM) i5-12600KF CPU at 3.70 GHz and 32 GB RAM"}],"baselines_and_workloads":[{"subtopic":"baselines_and_load","status":"OBSERVED","finding":"4 baselines (NPG, THR-G, LSTM-P, DTASM) under 20, 40, and 80 tasks/time-slot per swarm over 1000 time slots.","page":7,"locator":"VII.A-B","excerpt":"each swarm independently generates 20, 40, or 80 tasks per time-slot"}],"outcomes_latency_energy_communication_accuracy_reliability_and_scalability":[{"subtopic":"success_cost_accuracy","status":"OBSERVED","finding":"Promise achieves highest task success rate across 20/40/80 tasks/slot (Fig. 3), higher migration cost than THR-G/DTASM/NPG but lower than LSTM-P (Fig. 4), and preserves ResNet-18 accuracy (Fig. 5); exact values only in plots.","page":8,"locator":"VII.B Evaluation of Promise","excerpt":"Therefore, the Promise demonstrates continuous advantages across all experimental scenarios."}],"sensitivity_and_variability":[{"subtopic":"task_scale_sensitivity","status":"OBSERVED","finding":"Evaluated across 3 task arrival scales (20, 40, 80 tasks/time-slot); no multi-seed error bars reported.","page":7,"locator":"VII.A Experimental Settings","excerpt":"corresponding to three experimental scenarios."}],"code_and_data":[{"subtopic":"code_availability","status":"NOT_REPORTED","finding":"","page":9,"locator":"VIII. CONCLUSION","excerpt":"ACKNOWLEDGEMENT","reason":"No code repository URL or code availability statement found."}],"funding_and_conflicts":[{"subtopic":"funding","status":"OBSERVED","finding":"Supported in part by NSFC Grant 62572122.","page":9,"locator":"ACKNOWLEDGEMENT","excerpt":"National Natural Science Foundation of China under Grants 62572122."},{"subtopic":"conflicts","status":"NOT_REPORTED","finding":"","page":9,"locator":"ACKNOWLEDGEMENT","excerpt":"ACKNOWLEDGEMENT","reason":"No conflict of interest statement present."}],"reported_limitations":[{"subtopic":"future_work_limitations","status":"OBSERVED","finding":"Dynamic UAV joining/exiting across different operators, localization disruptions, and intermittent GCS connectivity remain for future work.","page":9,"locator":"VIII. CONCLUSION","excerpt":"anomalies such as locating disruptions and intermittent GCS connectivity, remain interests."}]},"quantitative_claims":[],"unresolved":[{"field_or_metric":"outcomes_quantitative_values","reason":"Task success rate (Fig. 3), total migration cost (Fig. 4), and average inference accuracy (Fig. 5) are presented only in plots without exact numeric values in text or tables.","source_checked":"R0002.pdf p.7-8 Section VII.B Fig. 3-5"}]}
{"report_id":"R0003","study_id":"S003","title":"Dynamic DNN Model Switching for Collaborative Edge Intelligence in UAV Swarm","authors":"Y. Li; Y. Qu; C. Dong; F. Zhou; L. Zhang; Q. Wu","year":2023,"venue":"2023 International Conference on Wireless Communications and Signal Processing (WCSP)","doi":"10.1109/WCSP58612.2023.10405273","pdf_path":"restart_2026_11_26/fulltext_retrieval/pdf/R0003.pdf","fields":{"identity":[{"subtopic":"bibliographic","status":"OBSERVED","finding":"2023 IEEE WCSP conference paper, 7 pages, DMS algorithm.","page":1,"locator":"Header","excerpt":"2023 IEEE the 15th International Conference on Wireless Communications and Signal Processing"}],"uav_architecture_role_and_topology":[{"subtopic":"swarm_roles","status":"OBSERVED","finding":"N UAVs (4-8 evaluated, default 5) in swarm; U1 is source/coordinator holding trajectory, channel, and task info, deciding local small model vs collaborative large model across swarm.","page":2,"locator":"III. SYSTEM MODEL","excerpt":"Within the swarm, UAV U1 has the information of all the UAVs' trajectories, channel conditions, and inference task distributions."}],"inference_model_task_and_dataset":[{"subtopic":"models_and_task","status":"OBSERVED","finding":"Image classification (ImageNet top-5 accuracy) switching between large model VGG16 (138M params, 91.90%) and small models AlexNet (62M params, 84.60%) or SqueezeNet (80.40%).","page":5,"locator":"V.A Simulation Settings","excerpt":"we employ VGG16 as the large complex model, while for the small lightweight model, we utilize both AlexNet and SqueezeNet."}],"partition_and_assignment":[{"subtopic":"per_layer_assignment","status":"OBSERVED","finding":"Small model runs entirely on U1; large model is partitioned layer-wise via binary variable alpha_r,n,j (each layer executed once on one UAV).","page":3,"locator":"III.B Latency Model","excerpt":"if UAV n performs inference on the j-th layer of the large complex model"}],"decision_variables_objectives_constraints_and_solver":[{"subtopic":"utility_ga_solver","status":"OBSERVED","finding":"Maximizes average normalized accuracy-latency utility (lambda1A - lambda2L) over model selection beta_r and layer assignment alpha_r,n,j under memory and compute constraints using Genetic Algorithm (DMS).","page":4,"locator":"IV. ALGORITHM DESIGN","excerpt":"we present a novel approach called DMS to address the problem discussed in Section 3, which is based on genetic algorithms"}],"compute_and_radio":[{"subtopic":"embedded_hardware_and_radio","status":"OBSERVED","finding":"Heterogeneous embedded devices (RPi Zero 1GHz/512MB, RPi 3B+ 1.4GHz/1GB, Odroid 1GHz/1GB, Orange Pi Zero 800MHz-1.2GHz/256MB, BeagleBone AI 1.5GHz/1GB; half RAM available); Rayleigh fading CN(0,1) + path loss + AWGN.","page":5,"locator":"V.A Simulation Settings","excerpt":"with each UAV equipped with different embedded devices, including Raspberry Pi Zero, Raspberry Pi 3B+, Odroid, Orange Pi Zero, and BeagleBone AI."}],"mobility_channel_intermittency_failure_and_recovery":[{"subtopic":"trace_mobility","status":"OBSERVED","finding":"Time-varying UAV-to-UAV distances and channel rates driven by real-world UAV trajectory traces [21]; failure/recovery not modeled.","page":5,"locator":"V.A Simulation Settings","excerpt":"the trajectories of the UAVs in our simulation are based on the real-world trajectory traces obtained from [21]."}],"evaluation_platform_simulator_hardware_and_traces":[{"subtopic":"traces","status":"OBSERVED","finding":"Trace-driven simulation using Mid-Air drone flight dataset [21] and ImageNet model accuracies.","page":5,"locator":"V.A Simulation Settings","excerpt":"the trajectories of the UAVs in our simulation are based on the real-world trajectory traces obtained from [21]."}],"baselines_and_workloads":[{"subtopic":"baselines_and_requests","status":"OBSERVED","finding":"4 baselines (GA-uniform, GA-random, Small-only, Large-only) under 4-8 inference requests (7 default) and 4-8 UAVs (5 default).","page":5,"locator":"V.A-B","excerpt":"we also introduced four baseline algorithms, namely GA-uniform, GA-random, Small-only, and Large-only."}],"outcomes_latency_energy_communication_accuracy_reliability_and_scalability":[{"subtopic":"latency_and_accuracy","status":"OBSERVED","finding":"With 5 UAVs and 7 requests, DMS achieves 22.67 s latency / 87.73% acc (VGG16+AlexNet) and 23.24 s / 85.32% acc (VGG16+SqueezeNet), cutting latency by 13.11%-21.09% vs GA baselines and 62.16% vs Large-only.","page":6,"locator":"Table 1 & V.B","excerpt":"the DMS algorithm exhibits an average latency reduction of 13.30% compared to GA-uniform"}],"sensitivity_and_variability":[{"subtopic":"requests_and_uavs","status":"OBSERVED","finding":"Evaluated across 4-8 inference requests (Fig. 2) and 4-8 UAVs (Fig. 3); gap over GA-uniform narrows as UAVs increase.","page":6,"locator":"V.B Results Analysis","excerpt":"as the number of UAVs increases, although DMS still outperforms GA-uniform, the gap between them gradually narrows."}],"code_and_data":[{"subtopic":"dataset_only","status":"OBSERVED","finding":"Uses public Mid-Air trajectory dataset [21]; code repository not reported.","page":5,"locator":"V.A Simulation Settings","excerpt":"real-world trajectory traces obtained from [21]."}],"funding_and_conflicts":[{"subtopic":"funding","status":"OBSERVED","finding":"Supported by NSFC Grant No. 61931011 and Grant No. 62072303.","page":7,"locator":"ACKNOWLEDGEMENT","excerpt":"National Natural Science Foundation of China under Grant No. 61931011 and Grant No. 62072303."},{"subtopic":"conflicts","status":"NOT_REPORTED","finding":"","page":7,"locator":"ACKNOWLEDGEMENT","excerpt":"ACKNOWLEDGEMENT","reason":"No conflict of interest statement present."}],"reported_limitations":[{"subtopic":"energy_omission","status":"OBSERVED","finding":"Energy consumption is omitted from the optimization and deferred to future work.","page":7,"locator":"VI. CONCLUSIONS","excerpt":"In future work, we will further investigate the impact of energy consumption on the UAV swarm"}]},"quantitative_claims":[{"metric":"average_latency_vgg16_alexnet","value":22.67,"units":"s","baseline":"GA-uniform (26.09 s), GA-random (28.73 s), Large-only (60.66 s), Small-only (7.25 s)","denominator":"7 inference requests","workload":"7 inference requests (VGG16 + AlexNet)","conditions":"5 heterogeneous UAVs, Mid-Air trajectories","page":6,"locator":"Table 1(a)","excerpt":"Average Latency (s) 22.67 26.09 28.73 7.25 60.66","status":"OBSERVED"},{"metric":"average_accuracy_vgg16_alexnet","value":87.73,"units":"%","baseline":"Small-only (84.60%), Large-only (91.90%)","denominator":"ImageNet top-5 accuracy","workload":"7 inference requests (VGG16 + AlexNet)","conditions":"5 heterogeneous UAVs","page":6,"locator":"Table 1(a)","excerpt":"Average Accuracy (%) 87.73 87.73 87.73 84.60 91.90","status":"OBSERVED"},{"metric":"average_latency_vgg16_squeezenet","value":23.24,"units":"s","baseline":"GA-uniform (26.86 s), GA-random (29.38 s), Large-only (60.66 s), Small-only (6.98 s)","denominator":"7 inference requests","workload":"7 inference requests (VGG16 + SqueezeNet)","conditions":"5 heterogeneous UAVs","page":6,"locator":"Table 1(b)","excerpt":"Average Latency (s) 23.24 26.86 29.38 6.98 60.66","status":"OBSERVED"},{"metric":"average_accuracy_vgg16_squeezenet","value":85.32,"units":"%","baseline":"Small-only (80.40%), Large-only (91.90%)","denominator":"ImageNet top-5 accuracy","workload":"7 inference requests (VGG16 + SqueezeNet)","conditions":"5 heterogeneous UAVs","page":6,"locator":"Table 1(b)","excerpt":"Average Accuracy (%) 85.32 85.32 85.32 80.40 91.90","status":"OBSERVED"},{"metric":"latency_reduction_vs_large_only","value":62.16,"units":"%","baseline":"Large-only","denominator":"Large-only average latency","workload":"7 inference requests","conditions":"5 UAVs, averaged across AlexNet and SqueezeNet configs","page":7,"locator":"V.B Results Analysis","excerpt":"DMS algorithm reduces the average latency by 62.16%.","status":"OBSERVED"}],"unresolved":[]}
